"""Authored PM7 Product Onboarding / Guided Tour cinematic module.

This transform is intentionally registration-neutral.  ``build_pm7.py`` may
register :func:`apply` after T44, but this source never edits the generated
PMConcept7 artifact itself.  The browser prototype uses only layered opacity,
translation, and scale motion so its visual vocabulary maps directly to Slint
states and transitions; it has no Canvas, WebGL, backdrop blur, SVG filter, or
heavy CSS filter dependency.
"""

from __future__ import annotations

import re

from pm7_transform_guards import (
    assert_protected_sources_equal,
    capture_effect_surfaces,
    capture_protected_sources,
)


