    need("cmd.onboarding." not in ONBOARDING_SCRIPT, "onboarding: false domain command family entered concept")
    for projection_fixture_token in (
        "pm.product_onboarding.automatic_preparation_owner_projection.v1",
        "pm.product_onboarding.automatic_preparation_projection_adapter.v1",
        "browser_concept_fixture_only",
        "production_owner_work:false",
        "production_readiness:false",
        "native_runtime_exercised:false",
        "production_receipt_ref:null",
        "We’ll let you know if we need one more choice.",
        "automatic_preparation_projection_currentness_mismatch",
        "explicit_retry",
    ):
        need(projection_fixture_token in ONBOARDING_SCRIPT, "onboarding: deterministic owner-projection fixture boundary missing: %s" % projection_fixture_token)
    for approved_geometry_or_copy in (
        ".pm7ob-window {",
        ".pm7ob-card { width: min(680px,100%);",
        ".pm7ob-hero-lockup { position: relative; width: 104px; height: 78px;",
        "Make it feel like yours.",
        "What brings you here?",
        "Keep every step recoverable.",
        "Choose where each part belongs.",
        "How should your devices connect?",
        "Everything waits for your say-so.",
    ):
        need(approved_geometry_or_copy in (ONBOARDING_STYLE + ONBOARDING_SCRIPT), "onboarding: approved creative geometry/copy drifted: %s" % approved_geometry_or_copy)
    expected_local_actions = {
        "ui.onboarding.start",
        "ui.onboarding.next",
        "ui.onboarding.back",
        "ui.onboarding.close",
        "ui.onboarding.skip",
        "ui.onboarding.defer",
        "ui.onboarding.open_details",
        "ui.onboarding.more_ways",
        "ui.onboarding.choose_simple_path",
        "ui.onboarding.open_owner_flow",
        "ui.onboarding.run_automatic_preparation",
        "ui.onboarding.choose_first_project",
        "ui.onboarding.finish",
    }
    actual_local_actions = set(re.findall(r"ui\.onboarding\.[a-z0-9_]+", ONBOARDING_MARKUP + ONBOARDING_SCRIPT))
    need(actual_local_actions == expected_local_actions, "onboarding: exact thirteen-action vocabulary drifted: %s" % sorted(actual_local_actions ^ expected_local_actions))
    for closure_token in (
        "pm.product_onboarding.action_request.v1",
        "pm.product_onboarding.action_result.v1",
        "action_request_log:actionRequestLog",
        "canonicalLocalActions=['ui.onboarding.start'",
        "local_context:localActionContext(id,payload)",
        "function localActionContext(id,payload)",
        "continuation_snapshot:sessionWritten?continuationSnapshot(returnFocusId):null",
        "revision:state.revision",
        "function defer()",
        "session_status_after:'deferred'",
        "resultOptions.status='rejected'",
        "owner_mutation_claimed:false",
        "if(!written)",
        "function toggleStageDetails()",
        "bounded_disclosure:true",
        "render({preserveFocus:true,persist:false})",
        "if(reason==='complete'){state.branch=null;renderBranch();}",
        "var deferButton=root.querySelector('.pm7ob-defer');",
        "var skipButton=root.querySelector('.pm7ob-skip');",
        "backButton.hidden=state.screen==='welcome';deferButton.hidden=ready;skipButton.hidden=ready;",
    ):
        need(closure_token in ONBOARDING_SCRIPT, "onboarding: defer/details/result closure token missing: %s" % closure_token)
    need("transition_serial+1" not in ONBOARDING_SCRIPT, "onboarding: UI animation serial was reused as durable action revision")
    for predecessor_action in (
        "ui.onboarding.choose_server_branch",
        "ui.onboarding.choose_provider",
        "ui.onboarding.choose_project",
    ):
        need(predecessor_action not in ONBOARDING_SCRIPT, "onboarding: predecessor action returned: %s" % predecessor_action)
    for forbidden in ("backdrop-filter", "filter:", "color-mix(", "url(#"):
        need(forbidden not in ONBOARDING_STYLE.lower(), "onboarding: non-portable visual primitive: %s" % forbidden)

    controls = re.findall(r"<button\b[^>]*>", ONBOARDING_MARKUP + ONBOARDING_SCRIPT, re.I)
    untyped = [control for control in controls if len(re.findall(r"\bdata-(?:command|ui-action)-id=", control)) != 1]
    need(not untyped, "onboarding: every authored button must carry exactly one typed action id")
    notes.update(
        {
            "decision": "simple cinematic first-run onboarding in a bounded modal window with the live shell visibly preserved behind it and a live-shell guided-tour handoff",
            "screen_order": ["welcome/theme", "starting path", "first project", "local history and online copy", "server/storage/client roles", "remote access", "review setup plan", "apply setup plan", "ready"],
            "dynamic_connect_order": ["welcome/theme", "starting path", "remote access and existing Server connection", "review setup plan", "apply setup plan", "ready"],
            "branch_ids": ["new_or_local", "connect_existing"],
            "timings_ms": {"hero": 1380, "step": 480, "stagger": 72, "micro": 180, "success": 700, "same_frame_ack": 0, "reduced_motion": 0},
            "slint_portability": "viewport overlay plus bounded modal rectangle, layered opacity/translation/scale states, Retro no-scale stepped reveals, and theme-token paint; no Canvas, WebGL, backdrop blur, SVG filter, or heavy CSS filters",
            "deterministic_api": "window.PM7_ONBOARDING_CINEMATIC",
            "persistence_boundary": "bounded no-secret browser concept adapter only; native durable binding remains Storage-owned",
            "owner_truth_boundary": "browser preparation state and optional determinate progress render only from an accepted exact-current concept owner projection; production readiness/work remain false, native runtime is unavailable, and no production receipt exists",
            "recovery_fixture_boundary": "pending, wait, input, blocked, failed, cancelled, recovery, and ready states enter only through the exact current owner-projection accept fence; browser fixtures remain non-production and receipt-free",
            "protected_embedded_source_guard": protected_receipt,
            "effect_surface_delta": {
                category: {
                    "added": sorted(effects_after[category] - effects_before[category]),
                    "removed": sorted(effects_before[category] - effects_after[category]),
                }
                for category in effects_before
            },
        }
    )
    return doc
